-- =====================================================================
-- 044 · Información de interés › Invitaciones a cotizar
--  Las 234 invitaciones publicadas en el portal anterior (2024-2026), con su PDF.
--  Quedan vigentes las publicadas desde el 2026-10-16; las demás, cerradas.
--  Cada fila se identifica con migrado_de = "<url anterior>#<id anterior>" para
--  no duplicarla. Las 3 sembradas en la 005 se marcan con su id y se cierran.
-- =====================================================================
SET NAMES utf8mb4;

UPDATE cms_cotizaciones SET migrado_de = 'esehospitalguaviare.gov.co/invitaciones-a-presentar-propuestas-cotizacion#437', estado = IF(estado = 'publicada', 'cerrada', estado) WHERE migrado_de = 'esehospitalguaviare.gov.co/invitaciones-a-presentar-propuestas-cotizacion' AND DATE(fecha_publicacion) = '2026-10-08';
UPDATE cms_cotizaciones SET migrado_de = 'esehospitalguaviare.gov.co/invitaciones-a-presentar-propuestas-cotizacion#436', estado = IF(estado = 'publicada', 'cerrada', estado) WHERE migrado_de = 'esehospitalguaviare.gov.co/invitaciones-a-presentar-propuestas-cotizacion' AND DATE(fecha_publicacion) = '2026-10-05';
UPDATE cms_cotizaciones SET migrado_de = 'esehospitalguaviare.gov.co/invitaciones-a-presentar-propuestas-cotizacion#432', estado = IF(estado = 'publicada', 'cerrada', estado) WHERE migrado_de = 'esehospitalguaviare.gov.co/invitaciones-a-presentar-propuestas-cotizacion' AND DATE(fecha_publicacion) = '2026-09-25';

